// Check all token tables for tokens expiring within 7 days
// Returns a list of token records that need refreshing, tagged by platform
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME

const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

const sevenDaysFromNow = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

async function fetchExpiringTokens(table, platform) {
  try {
    const res = await $helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/${table}?is_active=eq.true&token_expires_at=lte.${encodeURIComponent(sevenDaysFromNow)}&select=*`,
      headers: {
        'apikey':        serviceKey,
        'Authorization': `Bearer ${serviceKey}`
      }
    });
    const rows = typeof res === 'string' ? JSON.parse(res) : res;
    return (Array.isArray(rows) ? rows : []).map(r => ({ ...r, _platform: platform }));
  } catch (e) {
    console.error(`Failed to fetch ${table}: ${e.message}`);
    return [];
  }
}

const [linkedin, facebook, instagram, youtube, tiktok] = await Promise.all([
  fetchExpiringTokens('linkedin_tokens',  'linkedin'),
  fetchExpiringTokens('facebook_tokens',  'facebook'),
  fetchExpiringTokens('instagram_tokens', 'instagram'),
  fetchExpiringTokens('youtube_tokens',   'youtube'),
  fetchExpiringTokens('tiktok_tokens',    'tiktok')
]);

const allExpiring = [...linkedin, ...facebook, ...instagram, ...youtube, ...tiktok];

if (allExpiring.length === 0) {
  return [{ json: { status: 'no_tokens_expiring', checked_at: new Date().toISOString() } }];
}

return allExpiring.map(t => ({ json: t }));

// Refresh tokens by platform
// LinkedIn: cannot auto-refresh — send re-auth email notification
// Facebook/Instagram: exchange for new long-lived token using current token
// YouTube: use refresh_token with Google OAuth
// TikTok: use refresh_token with TikTok OAuth v2
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME

const token    = $input.first().json;
const platform = token._platform;
const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

async function updateToken(table, memberEmail, updates) {
  await $helpers.httpRequest({
    method: 'PATCH',
    url: `${supabaseUrl}/rest/v1/${table}?member_email=eq.${encodeURIComponent(memberEmail)}`,
    headers: {
      'Content-Type':  'application/json',
      'apikey':        serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
      'Prefer':        'return=minimal'
    },
    body: JSON.stringify(updates)
  });
}

const now = new Date();

if (platform === 'linkedin') {
  // LinkedIn access tokens last 60 days and cannot be refreshed programmatically.
  // Mark as expiring and return — a separate notification workflow should email the member.
  return [{
    json: {
      platform,
      member_email: token.member_email,
      action: 'needs_reauth',
      message: 'LinkedIn token cannot be refreshed automatically. Member must re-authenticate.',
      expires_at: token.token_expires_at
    }
  }];
}

if (platform === 'facebook' || platform === 'instagram') {
  const appId     = $env.FACEBOOK_APP_ID;
  const appSecret = $env.FACEBOOK_APP_SECRET;
  try {
    const res = await $helpers.httpRequest({
      method: 'GET',
      url: `https://graph.facebook.com/v18.0/oauth/access_token?grant_type=fb_exchange_token&client_id=${appId}&client_secret=${appSecret}&fb_exchange_token=${encodeURIComponent(token.access_token)}`
    });
    const data = typeof res === 'string' ? JSON.parse(res) : res;
    if (data.error) throw new Error(data.error.message);

    const newExpiry = new Date(now.getTime() + (data.expires_in || 5184000) * 1000);
    const table = platform === 'facebook' ? 'facebook_tokens' : 'instagram_tokens';
    await updateToken(table, token.member_email, {
      access_token:     data.access_token,
      expires_in:       data.expires_in,
      token_stored_at:  now.toISOString(),
      token_expires_at: newExpiry.toISOString()
    });
    return [{ json: { platform, member_email: token.member_email, action: 'refreshed', new_expiry: newExpiry.toISOString() } }];
  } catch (e) {
    return [{ json: { platform, member_email: token.member_email, action: 'refresh_failed', error: e.message } }];
  }
}

if (platform === 'youtube') {
  if (!token.refresh_token) {
    return [{ json: { platform, member_email: token.member_email, action: 'needs_reauth', message: 'No refresh token available' } }];
  }
  const clientId     = $env.YOUTUBE_CLIENT_ID;
  const clientSecret = $env.YOUTUBE_CLIENT_SECRET;
  try {
    const params = new URLSearchParams({
      client_id:     clientId,
      client_secret: clientSecret,
      refresh_token: token.refresh_token,
      grant_type:    'refresh_token'
    });
    const res = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://oauth2.googleapis.com/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString()
    });
    const data = typeof res === 'string' ? JSON.parse(res) : res;
    if (data.error) throw new Error(data.error_description || data.error);

    const expiresIn  = data.expires_in || 3600;
    const newExpiry  = new Date(now.getTime() + expiresIn * 1000);
    await updateToken('youtube_tokens', token.member_email, {
      access_token:     data.access_token,
      expires_in:       expiresIn,
      token_stored_at:  now.toISOString(),
      token_expires_at: newExpiry.toISOString()
    });
    return [{ json: { platform, member_email: token.member_email, action: 'refreshed', new_expiry: newExpiry.toISOString() } }];
  } catch (e) {
    return [{ json: { platform, member_email: token.member_email, action: 'refresh_failed', error: e.message } }];
  }
}

if (platform === 'tiktok') {
  if (!token.refresh_token) {
    return [{ json: { platform, member_email: token.member_email, action: 'needs_reauth', message: 'No refresh token available' } }];
  }
  const clientKey    = $env.TIKTOK_CLIENT_KEY;
  const clientSecret = $env.TIKTOK_CLIENT_SECRET;
  try {
    const params = new URLSearchParams({
      client_key:    clientKey,
      client_secret: clientSecret,
      grant_type:    'refresh_token',
      refresh_token: token.refresh_token
    });
    const res = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://open.tiktokapis.com/v2/oauth/token/',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString()
    });
    const data = typeof res === 'string' ? JSON.parse(res) : res;
    if (data.error) throw new Error(data.error_description || data.error);

    const expiresIn       = data.expires_in || 86400;
    const refreshExpires  = data.refresh_expires_in || 31536000;
    const newExpiry       = new Date(now.getTime() + expiresIn * 1000);
    const newRefreshExpiry = new Date(now.getTime() + refreshExpires * 1000);
    await updateToken('tiktok_tokens', token.member_email, {
      access_token:       data.access_token,
      refresh_token:      data.refresh_token,
      expires_in:         expiresIn,
      refresh_expires_in: refreshExpires,
      token_stored_at:    now.toISOString(),
      token_expires_at:   newExpiry.toISOString(),
      refresh_expires_at: newRefreshExpiry.toISOString()
    });
    return [{ json: { platform, member_email: token.member_email, action: 'refreshed', new_expiry: newExpiry.toISOString() } }];
  } catch (e) {
    return [{ json: { platform, member_email: token.member_email, action: 'refresh_failed', error: e.message } }];
  }
}

return [{ json: { platform, member_email: token.member_email, action: 'unknown_platform' } }];
